function solve(matrix, target) {
  const rows = matrix.length;
  if (rows === 0) return [-1, -1];
  const cols = matrix[0].length;
  if (cols === 0) return [-1, -1];
  let first = -1;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (matrix[i][j] !== target) continue;
      let rank = 0;
      for (let a = 0; a < rows; a++) {
        for (let b = 0; b < cols; b++) {
          const value = matrix[a][b];
          if (value < target) rank++;
          else if (value === target && (a < i || (a === i && b < j))) rank++;
        }
      }
      if (first === -1 || rank < first) first = rank;
    }
  }
  if (first === -1) return [-1, -1];
  return [Math.floor(first / cols), first % cols];
}

function solve(matrix, target) {
  const rows = matrix.length;
  if (rows === 0) return [-1, -1];
  const cols = matrix[0].length;
  if (cols === 0) return [-1, -1];
  let smaller = 0;
  let found = false;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      const value = matrix[i][j];
      if (value < target) smaller++;
      else if (value === target) found = true;
    }
  }
  if (!found) return [-1, -1];
  return [Math.floor(smaller / cols), smaller % cols];
}
